const tp = require('timers/promises');
console.log(tp === require('node:timers/promises'), tp === require('timers').promises);
(async () => {
  const t0 = Date.now();
  const v = await tp.setTimeout(20, 'val');
  console.log('setTimeout resolved', v, Date.now() - t0 >= 19);
  const v2 = await tp.setImmediate('imm');
  console.log('setImmediate resolved', v2);
  const ac = new AbortController();
  const p = tp.setTimeout(1000, 'never', { signal: ac.signal });
  ac.abort();
  try { await p; } catch (e) { console.log('aborted:', e.name, e.message, e.code, e.constructor.name, e.cause === undefined, JSON.stringify(Object.keys(e))); }
  const ac2 = new AbortController();
  ac2.abort('custom reason');
  try { await tp.setTimeout(10, 'x', { signal: ac2.signal }); } catch (e) { console.log('pre-aborted:', typeof e, e.name, e.message, e.code, String(e.cause)); }
  try { await tp.setImmediate('x', { signal: ac2.signal }); } catch (e) { console.log('imm pre-aborted:', e.name, e.message, e.code); }
  let n = 0;
  for await (const x of tp.setInterval(10, 'tick')) {
    console.log('interval', x, ++n);
    if (n >= 3) break;
  }
  const ac3 = new AbortController();
  setTimeout(() => ac3.abort(), 25);
  try {
    for await (const x of tp.setInterval(10, 'i2', { signal: ac3.signal })) { console.log('i2', x); }
  } catch (e) { console.log('interval aborted', e.name, e.message, e.code); }
  await tp.scheduler.wait(10);
  console.log('waited');
  const y = await tp.scheduler.yield();
  console.log('yielded', y);
  const d = await tp.setTimeout();
  console.log('default', d);
  try { await tp.setTimeout(10, 'v', null) } catch (e) { console.log('null opts', e.name, e.message) }
  try { await tp.setTimeout(10, 'v', 'str'); console.log('str opts ok') } catch (e) { console.log('str opts', e.name, e.message) }
  const it = tp.setInterval(5);
  console.log(Object.prototype.toString.call(it), typeof it.next, typeof it[Symbol.asyncIterator]);
  const r1 = await it.next();
  console.log(JSON.stringify(r1));
  await it.return();
  console.log(JSON.stringify(await it.next()));
})();

