pub fn this_ta(vm: &mut Vm, v: &Value) -> JsResult<(Obj, TAKind, usize)> {
    match v {
        Value::Obj(o) => {
            let r = match &o.borrow().kind {
                ObjKind::TypedArray(t) => Some((t.kind, t.len(), t.is_out_of_bounds())),
                _ => None,
            };
            match r {
                Some((k, l, oob)) => {
                    if oob {
                        return vm.throw_type("Cannot perform %TypedArray%.prototype method on a detached ArrayBuffer");
                    }
                    Ok((o.clone(), k, l))
                }
                None => vm.throw_type("this is not a typed array."),
            }
        }
        _ => vm.throw_type("this is not a typed array."),
    }
}

