thread_local! {
    /// BroadcastChannel registry: channel name -> open channels (insertion ordered).
    static CHANNELS: RefCell<Vec<(JsStr, Vec<Obj>)>> = RefCell::new(Vec::new());
    static HANDLER_SYMS: RefCell<Option<(Sym, Sym, Sym, Sym)>> = RefCell::new(None);
}

fn setup_messaging(vm: &mut Vm) {
    let (c, p) = make_class(vm, "MessagePort", "MessagePort.prototype", 1, message_port_ctor, Some("EventTarget"));
    method(vm, &p, "postMessage", 2, port_post_message);
    method(vm, &p, "start", 0, port_start);
    method(vm, &p, "close", 0, port_close);
    method(vm, &p, "_deliver", 1, port_deliver);
    method(vm, &p, "_dispatch", 1, port_dispatch);
    define_handler(vm, &p, "message", true);
    define_handler(vm, &p, "messageerror", false);
    set_global(vm, "MessagePort", Value::Obj(c));

    let (c, _p) = make_class(vm, "MessageChannel", "MessageChannel.prototype", 0, message_channel_ctor, None);
    set_global(vm, "MessageChannel", Value::Obj(c));

    let (c, p) = make_class(vm, "BroadcastChannel", "BroadcastChannel.prototype", 1, broadcast_channel_ctor, Some("EventTarget"));
    method(vm, &p, "postMessage", 1, bc_post_message);
    method(vm, &p, "close", 0, bc_close);
    define_handler(vm, &p, "message", false);
    define_handler(vm, &p, "messageerror", false);
    set_global(vm, "BroadcastChannel", Value::Obj(c));
}

fn handler_syms(event: &str) -> (Sym, Sym) {
    HANDLER_SYMS.with(|h| {
        let mut h = h.borrow_mut();
        if h.is_none() {
            *h = Some((
                Sym::new_private(JsStr::from_str("onmessage handler")),
                Sym::new_private(JsStr::from_str("onmessage listener")),
                Sym::new_private(JsStr::from_str("onmessageerror handler")),
                Sym::new_private(JsStr::from_str("onmessageerror listener")),
            ));
        }
        let t = h.as_ref().unwrap();
        if event == "message" {
            (t.0.clone(), t.1.clone())
        } else {
            (t.2.clone(), t.3.clone())
        }
    })
}

/// `on<event>` accessor pair backed by per-object handler/listener slots.
fn define_handler(vm: &mut Vm, proto: &Obj, event: &str, start_after_set: bool) {
    let ev = Value::str(event);
    let g = vm.native_closure("get", 0, handler_get, vec![ev.clone()]);
    let s = vm.native_closure("set", 1, handler_set, vec![ev, Value::Bool(start_after_set)]);
    proto.set_accessor(key(&format!("on{}", event)), Some(g), Some(s), CONFIGURABLE);
}

fn hidden_get(o: &Value, sym: &Sym) -> Option<Value> {
    match o {
        Value::Obj(ob) => ob.get_own_data(&PropKey::Sym(sym.clone())),
        _ => None,
    }
}

fn hidden_set(o: &Value, sym: &Sym, v: Option<Value>) {
    if let Value::Obj(ob) = o {
        let k = PropKey::Sym(sym.clone());
        match v {
            Some(v) => ob.set_prop(k, v, WC),
            None => {
                ob.borrow_mut().props.remove(&k);
            }
        }
    }
}

fn handler_get(_vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let ev = a.slot(0);
    let evs = match &ev {
        Value::Str(s) => s.to_rust_string(),
        _ => String::new(),
    };
    let (hs, _) = handler_syms(&evs);
    Ok(hidden_get(&a.this, &hs).unwrap_or(Value::Null))
}

fn handler_set(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let ev = a.slot(0);
    let start_after = a.slot(1).truthy();
    let evs = match &ev {
        Value::Str(s) => s.to_rust_string(),
        _ => String::new(),
    };
    let (hs, ls) = handler_syms(&evs);
    let this = a.this.clone();
    let f = a.arg(0);
    if let Some(old) = hidden_get(&this, &ls) {
        invoke(vm, &this, "removeEventListener", &[ev.clone(), old])?;
    }
    if f.is_callable() {
        hidden_set(&this, &hs, Some(f.clone()));
        let wrapped = vm.native_closure("", 1, handler_wrapper, vec![f, this.clone()]);
        hidden_set(&this, &ls, Some(Value::Obj(wrapped.clone())));
        invoke(vm, &this, "addEventListener", &[ev, Value::Obj(wrapped)])?;
    } else {
        hidden_set(&this, &hs, None);
        hidden_set(&this, &ls, None);
    }
    if start_after {
        invoke(vm, &this, "start", &[])?;
    }
    Ok(Value::Undefined)
}

/// `(e) => fn.call(this, e)`
fn handler_wrapper(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let f = a.slot(0);
    let this = a.slot(1);
    vm.call(&f, this, &[a.arg(0)])
}

fn message_port_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if a.new_target.is_none() {
        return class_call_error(vm);
    }
    vm.throw_type("Illegal constructor")
}

/// `new MessagePort(kPortCreate)`
fn create_port(vm: &mut Vm) -> JsResult<Value> {
    let p = reg(vm, "MessagePort.prototype");
    let ov = Value::Obj(Obj::new(Some(p), ObjKind::Ordinary));
    event_target_init(vm, &ov)?;
    set(vm, &ov, "_other", Value::Null)?;
    let q = array(vm, Vec::new());
    set(vm, &ov, "_queue", q)?;
    set(vm, &ov, "_started", Value::Bool(false))?;
    set(vm, &ov, "_closed", Value::Bool(false))?;
    Ok(ov)
}

fn port_post_message(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    if get(vm, &this, "_closed")?.truthy() {
        return Ok(Value::Undefined);
    }
    let options = a.arg(1);
    let is_arr = crate::builtins::array::is_array(vm, &options)?;
    let transfer = if is_arr {
        options.clone()
    } else if options.truthy() && is_object_type(&options) && get(vm, &options, "transfer")?.truthy() {
        get(vm, &options, "transfer")?
    } else {
        array(vm, Vec::new())
    };
    let _ = get(vm, &transfer, "length")?;
    let data = super::clone::structured_clone(vm, &a.arg(0))?;
    let target = get(vm, &this, "_other")?;
    if !target.truthy() || get(vm, &target, "_closed")?.truthy() {
        return Ok(Value::Undefined);
    }
    let cb = vm.native_closure("", 0, port_deliver_task, vec![target, data]);
    crate::runtime::timers::add_timer(vm, Value::Obj(cb), 0.0, Vec::new(), false);
    Ok(Value::Undefined)
}

/// `() => target._deliver(data)`
fn port_deliver_task(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let target = a.slot(0);
    let data = a.slot(1);
    invoke(vm, &target, "_deliver", &[data])
}

fn port_start(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    if get(vm, &this, "_started")?.truthy() || get(vm, &this, "_closed")?.truthy() {
        return Ok(Value::Undefined);
    }
    set(vm, &this, "_started", Value::Bool(true))?;
    let q = get(vm, &this, "_queue")?;
    let queued = invoke(vm, &q, "splice", &[Value::Num(0.0)])?;
    for data in vm.iterate_to_vec(&queued)? {
        let cb = vm.native_closure("", 0, port_dispatch_task, vec![this.clone(), data]);
        crate::runtime::timers::add_timer(vm, Value::Obj(cb), 0.0, Vec::new(), false);
    }
    Ok(Value::Undefined)
}

/// `() => this._dispatch(data)`
fn port_dispatch_task(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let port = a.slot(0);
    let data = a.slot(1);
    invoke(vm, &port, "_dispatch", &[data])
}

fn port_close(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    set(vm, &this, "_closed", Value::Bool(true))?;
    let other = get(vm, &this, "_other")?;
    if other.truthy() {
        let other = get(vm, &this, "_other")?;
        set(vm, &other, "_other", Value::Null)?;
    }
    set(vm, &this, "_other", Value::Null)?;
    Ok(Value::Undefined)
}

fn port_deliver(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    if get(vm, &this, "_closed")?.truthy() {
        return Ok(Value::Undefined);
    }
    if !get(vm, &this, "_started")?.truthy() {
        let q = get(vm, &this, "_queue")?;
        arr_push(vm, &q, a.arg(0))?;
        return Ok(Value::Undefined);
    }
    invoke(vm, &this, "_dispatch", &[a.arg(0)])?;
    Ok(Value::Undefined)
}

fn port_dispatch(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    if get(vm, &this, "_closed")?.truthy() {
        return Ok(Value::Undefined);
    }
    let ev = new_message_event(vm, a.arg(0))?;
    invoke(vm, &this, "dispatchEvent", &[ev])?;
    Ok(Value::Undefined)
}

fn message_channel_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = new_this(vm, a, "MessageChannel.prototype")?;
    let ov = Value::Obj(o);
    let p1 = create_port(vm)?;
    let p2 = create_port(vm)?;
    set(vm, &p1, "_other", p2.clone())?;
    set(vm, &p2, "_other", p1.clone())?;
    set(vm, &ov, "port1", p1)?;
    set(vm, &ov, "port2", p2)?;
    Ok(ov)
}

fn broadcast_channel_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if a.new_target.is_none() {
        return class_call_error(vm);
    }
    if a.args.is_empty() {
        return vm.throw_type("BroadcastChannel requires a name");
    }
    let o = new_this(vm, a, "BroadcastChannel.prototype")?;
    let ov = Value::Obj(o.clone());
    event_target_init(vm, &ov)?;
    let name = js_string(vm, &a.arg(0))?;
    set(vm, &ov, "name", Value::Str(name))?;
    set(vm, &ov, "_closed", Value::Bool(false))?;
    let n = get(vm, &ov, "name")?;
    let n = js_string(vm, &n)?;
    CHANNELS.with(|c| {
        let mut c = c.borrow_mut();
        match c.iter_mut().find(|(k, _)| *k == n) {
            Some((_, set)) => {
                if !set.iter().any(|x| x.ptr_eq(&o)) {
                    set.push(o.clone());
                }
            }
            None => c.push((n, vec![o.clone()])),
        }
    });
    Ok(ov)
}

fn bc_post_message(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    if get(vm, &this, "_closed")?.truthy() {
        return throw_dom(vm, "BroadcastChannel is closed", "InvalidStateError");
    }
    let data = super::clone::structured_clone(vm, &a.arg(0))?;
    let n = get(vm, &this, "name")?;
    let n = js_string(vm, &n)?;
    let members: Vec<Obj> = CHANNELS.with(|c| c.borrow().iter().find(|(k, _)| *k == n).map(|(_, s)| s.clone()).unwrap_or_default());
    let mut peers = Vec::new();
    for m in members {
        let mv = Value::Obj(m.clone());
        if let Value::Obj(t) = &this {
            if t.ptr_eq(&m) {
                continue;
            }
        }
        if get(vm, &mv, "_closed")?.truthy() {
            continue;
        }
        peers.push(mv);
    }
    let peers = array(vm, peers);
    let cb = vm.native_closure("", 0, bc_deliver_task, vec![peers, data]);
    crate::runtime::timers::add_timer(vm, Value::Obj(cb), 0.0, Vec::new(), false);
    Ok(Value::Undefined)
}

fn bc_deliver_task(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let peers = a.slot(0);
    let data = a.slot(1);
    for peer in list_items(vm, &peers)? {
        if get(vm, &peer, "_closed")?.truthy() {
            continue;
        }
        let d = super::clone::structured_clone(vm, &data)?;
        let ev = new_message_event(vm, d)?;
        invoke(vm, &peer, "dispatchEvent", &[ev])?;
    }
    Ok(Value::Undefined)
}

fn bc_close(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let this = a.this.clone();
    set(vm, &this, "_closed", Value::Bool(true))?;
    let n = get(vm, &this, "name")?;
    let n = js_string(vm, &n)?;
    if let Value::Obj(o) = &this {
        CHANNELS.with(|c| {
            let mut c = c.borrow_mut();
            if let Some(pos) = c.iter().position(|(k, _)| *k == n) {
                c[pos].1.retain(|x| !x.ptr_eq(o));
                if c[pos].1.is_empty() {
                    c.remove(pos);
                }
            }
        });
    }
    Ok(Value::Undefined)
}

// =============================================================================================
// reportError / onerror / onunhandledrejection / queueMicrotask
// =============================================================================================

pub fn setup_late(vm: &mut Vm) {
    let qm = vm.native_fn("", 1, queue_microtask);
    set_global(vm, "queueMicrotask", Value::Obj(qm));
    set_global(vm, "onerror", Value::Null);
    set_global(vm, "onunhandledrejection", Value::Null);
    let re = plain_fn(vm, "reportError", 1, report_error);
    set_global(vm, "reportError", Value::Obj(re));
}

/// `(cb) => { if (typeof cb !== 'function') throw new TypeError(...); Promise.resolve().then(cb); }`
pub fn queue_microtask(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let cb = a.arg(0);
    if !cb.is_callable() {
        return vm.throw_type("queueMicrotask expects a function");
    }
    let p = crate::builtins::promise::promise_resolve_intrinsic(vm, Value::Undefined)?;
    crate::builtins::promise::promise_then(vm, &p, cb, Value::Undefined)?;
    Ok(Value::Undefined)
}

fn report_error(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if a.args.is_empty() {
        return vm.throw_type("reportError requires at least 1 argument");
    }
    report_error_value(vm, &a.arg(0));
    Ok(Value::Undefined)
}

/// Offer `e` to `globalThis.onerror(message, "", 0, 0, e)`; true when it returned `true`.
pub fn fire_onerror(vm: &mut Vm, e: &Value) -> bool {
    let h = match global_get(vm, "onerror") {
        Ok(h) => h,
        Err(_) => return false,
    };
    if !h.is_callable() {
        return false;
    }
    let msg = format!("Uncaught {}", describe_reported(vm, e));
    let g = Value::Obj(vm.global.clone());
    match vm.call(&h, g, &[Value::str(&msg), Value::str(""), Value::Num(0.0), Value::Num(0.0), e.clone()]) {
        Ok(Value::Bool(true)) => true,
        _ => false,
    }
}

/// `if (!fire(e)) report(e)`
pub fn report_error_value(vm: &mut Vm, e: &Value) {
    if fire_onerror(vm, e) {
        return;
    }
    let s = describe_reported(vm, e);
    crate::runtime::write_stderr(&format!("Uncaught {}\n", s));
}

/// Offer an unhandled rejection to `globalThis.onunhandledrejection`; true when prevented.
pub fn fire_unhandled_rejection(vm: &mut Vm, promise: &Value, reason: &Value) -> bool {
    let h = match global_get(vm, "onunhandledrejection") {
        Ok(h) => h,
        Err(_) => return false,
    };
    if !h.is_callable() {
        return false;
    }
    let flag = vm.new_object();
    flag.set_prop(key("prevented"), Value::Bool(false), WEC);
    let ev = plain(vm, vec![
        ("type", Value::str("unhandledrejection")),
        ("promise", promise.clone()),
        ("reason", reason.clone()),
        ("cancelable", Value::Bool(true)),
    ]);
    let pd = vm.native_closure("preventDefault", 0, rejection_prevent_default, vec![Value::Obj(flag.clone())]);
    ev.set_prop(key("preventDefault"), Value::Obj(pd), WEC);
    let g = vm.native_closure("get defaultPrevented", 0, rejection_default_prevented, vec![Value::Obj(flag.clone())]);
    ev.set_accessor(key("defaultPrevented"), Some(g), None, ENUMERABLE | CONFIGURABLE);
    let gv = Value::Obj(vm.global.clone());
    let _ = vm.call(&h, gv, &[Value::Obj(ev)]);
    matches!(flag.get_own_str("prevented"), Some(Value::Bool(true)))
}

fn rejection_prevent_default(_vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if let Value::Obj(f) = a.slot(0) {
        f.set_prop(key("prevented"), Value::Bool(true), WEC);
    }
    Ok(Value::Undefined)
}

fn rejection_default_prevented(_vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if let Value::Obj(f) = a.slot(0) {
        return Ok(f.get_own_str("prevented").unwrap_or(Value::Bool(false)));
    }
    Ok(Value::Bool(false))
}

// TextEncoder / TextDecoder / atob / btoa.
//
// The reference engine keeps strings as UTF-8 internally and escapes lone surrogates into the
// top of plane 16 (U+10F800..U+10FFFF = surrogate + 0x102000); TextEncoder exposes those
// internal bytes and TextDecoder maps that range back to lone surrogates.

use super::*;
use crate::object::*;
use crate::value::*;
use crate::vm::{JsResult, Vm};

const ESCAPE_BASE: u32 = 0x10F800;
const ESCAPE_OFFSET: u32 = 0x102000;

fn push_utf8(out: &mut Vec<u8>, cp: u32) {
    if cp < 0x80 {
        out.push(cp as u8);
    } else if cp < 0x800 {
        out.push(0xC0 | (cp >> 6) as u8);
        out.push(0x80 | (cp & 0x3F) as u8);
    } else if cp < 0x10000 {
        out.push(0xE0 | (cp >> 12) as u8);
        out.push(0x80 | ((cp >> 6) & 0x3F) as u8);
        out.push(0x80 | (cp & 0x3F) as u8);
    } else {
        out.push(0xF0 | (cp >> 18) as u8);
        out.push(0x80 | ((cp >> 12) & 0x3F) as u8);
        out.push(0x80 | ((cp >> 6) & 0x3F) as u8);
        out.push(0x80 | (cp & 0x3F) as u8);
    }
}

/// UTF-16 string -> the engine's internal UTF-8 bytes.
pub fn engine_utf8(units: &[u16]) -> Vec<u8> {
    let mut out = Vec::with_capacity(units.len());
    let mut i = 0;
    while i < units.len() {
        let u = units[i] as u32;
        if (0xD800..0xDC00).contains(&u) && i + 1 < units.len() {
            let l = units[i + 1] as u32;
            if (0xDC00..0xE000).contains(&l) {
                let cp = 0x10000 + ((u - 0xD800) << 10) + (l - 0xDC00);
                if cp < ESCAPE_BASE {
                    push_utf8(&mut out, cp);
                    i += 2;
                    continue;
                }
            }
        }
        if (0xD800..0xE000).contains(&u) {
            push_utf8(&mut out, u + ESCAPE_OFFSET);
        } else {
            push_utf8(&mut out, u);
        }
        i += 1;
    }
    out
}

/// UTF-8 bytes -> UTF-16 (invalid sequences become U+FFFD, escaped surrogates come back).
pub fn engine_utf16(bytes: &[u8]) -> Vec<u16> {
    let s = String::from_utf8_lossy(bytes);
    let mut out = Vec::with_capacity(s.len());
    for c in s.chars() {
        let cp = c as u32;
        if cp >= ESCAPE_BASE {
            out.push((cp - ESCAPE_OFFSET) as u16);
        } else if cp >= 0x10000 {
            let v = cp - 0x10000;
            out.push(0xD800 + (v >> 10) as u16);
            out.push(0xDC00 + (v & 0x3FF) as u16);
        } else {
            out.push(cp as u16);
        }
    }
    out
}

pub fn setup(vm: &mut Vm) {
    let (c, p) = make_class(vm, "TextEncoder", "TextEncoder.prototype", 0, text_encoder_ctor, None);
    getter(vm, &p, "encoding", |_vm, _a| Ok(Value::str("utf-8")));
    method(vm, &p, "encode", 0, text_encoder_encode);
    set_global(vm, "TextEncoder", Value::Obj(c));

    let (c, p) = make_class(vm, "TextDecoder", "TextDecoder.prototype", 0, text_decoder_ctor, None);
    method(vm, &p, "decode", 1, text_decoder_decode);
    set_global(vm, "TextDecoder", Value::Obj(c));

    let f = plain_fn(vm, "btoa", 1, btoa);
    set_global(vm, "btoa", Value::Obj(f));
    let f = plain_fn(vm, "atob", 1, atob);
    set_global(vm, "atob", Value::Obj(f));
}

fn text_encoder_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    Ok(Value::Obj(new_this(vm, a, "TextEncoder.prototype")?))
}

/// `__encoding.encode(String(input))`
pub fn encode_to_u8(vm: &mut Vm, s: &JsStr) -> Value {
    let bytes = engine_utf8(s.units());
    Value::Obj(crate::builtins::typedarray::typed_array_from_bytes(vm, bytes))
}

fn text_encoder_encode(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let input = if a.arg(0).is_undefined() { Value::str("") } else { a.arg(0) };
    let s = js_string(vm, &input)?;
    Ok(encode_to_u8(vm, &s))
}

fn text_decoder_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let o = new_this(vm, a, "TextDecoder.prototype")?;
    let ov = Value::Obj(o);
    let label = if a.arg(0).is_undefined() { Value::str("utf-8") } else { a.arg(0) };
    let l = js_string(vm, &label)?.to_rust_string().to_lowercase();
    if l != "utf-8" && l != "utf8" && l != "unicode-1-1-utf-8" {
        let shown = vm.to_string(&label)?;
        return vm.throw_range(format!("TextDecoder: unsupported encoding '{}' (utf-8 only for now)", shown));
    }
    let options = if a.arg(1).is_undefined() { Value::Obj(vm.new_object()) } else { a.arg(1) };
    let options = if options.truthy() && is_object_type(&options) { options } else { Value::Obj(vm.new_object()) };
    set(vm, &ov, "encoding", Value::str("utf-8"))?;
    let fatal = get(vm, &options, "fatal")?.truthy();
    set(vm, &ov, "fatal", Value::Bool(fatal))?;
    let ib = get(vm, &options, "ignoreBOM")?.truthy();
    set(vm, &ov, "ignoreBOM", Value::Bool(ib))?;
    Ok(ov)
}

/// Bytes of a BufferSource accepted by `__encoding.decode` (typed arrays only).
fn typed_bytes(v: &Value) -> Option<Vec<u8>> {
    if let Value::Obj(o) = v {
        if let ObjKind::TypedArray(_) = &o.borrow().kind {
            return Some(crate::builtins::typedarray::ta_bytes(o));
        }
    }
    None
}

/// Decode UTF-8 bytes; `fatal` errors on malformed input.
pub fn decode_utf8(vm: &mut Vm, bytes: &[u8], fatal: bool) -> JsResult<JsStr> {
    if fatal && std::str::from_utf8(bytes).is_err() {
        return vm.throw_type("TextDecoder: invalid utf-8 (fatal)");
    }
    Ok(JsStr::from_units(engine_utf16(bytes)))
}

/// `new TextDecoder().decode(bytes)` (BOM stripped, replacement on errors)
pub fn decode_default(bytes: &[u8]) -> JsStr {
    let mut u = engine_utf16(bytes);
    if u.first() == Some(&0xFEFF) {
        u.remove(0);
    }
    JsStr::from_units(u)
}

fn text_decoder_decode(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let mut input = a.arg(0);
    if input.is_undefined() {
        return Ok(Value::str(""));
    }
    let abp = vm.intr.array_buffer_proto.clone();
    if has_in_chain(vm, &input, &abp)? {
        if let Value::Obj(o) = &input {
            if let ObjKind::ArrayBuffer(_) = &o.borrow().kind {
                let bytes = crate::builtins::typedarray::ta_bytes(o);
                input = Value::Obj(crate::builtins::typedarray::typed_array_from_bytes(vm, bytes));
            }
        }
    }
    let fatal = get(vm, &a.this, "fatal")?.truthy();
    let bytes = match typed_bytes(&input) {
        Some(b) => b,
        None => return vm.throw_type("TextDecoder.decode expects a BufferSource"),
    };
    let s = decode_utf8(vm, &bytes, fatal)?;
    let ib = get(vm, &a.this, "ignoreBOM")?.truthy();
    if !ib && s.units().first() == Some(&0xFEFF) {
        return Ok(Value::Str(s.substring(1, s.len())));
    }
    Ok(Value::Str(s))
}

const B64: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

fn btoa(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let s = js_string(vm, &a.arg(0))?;
    let u = s.units();
    let mut out = String::with_capacity(u.len() / 3 * 4 + 4);
    let mut i = 0;
    while i < u.len() {
        let c0 = u[i] as u32;
        let c1 = u.get(i + 1).map(|&x| x as u32);
        let c2 = u.get(i + 2).map(|&x| x as u32);
        if c0 > 255 || c1.map_or(false, |c| c > 255) || c2.map_or(false, |c| c > 255) {
            return throw_dom(vm, "btoa: character beyond latin1 range", "InvalidCharacterError");
        }
        let n = (c0 << 16) | (c1.unwrap_or(0) << 8) | c2.unwrap_or(0);
        out.push(B64[((n >> 18) & 63) as usize] as char);
        out.push(B64[((n >> 12) & 63) as usize] as char);
        out.push(if i + 1 < u.len() { B64[((n >> 6) & 63) as usize] as char } else { '=' });
        out.push(if i + 2 < u.len() { B64[(n & 63) as usize] as char } else { '=' });
        i += 3;
    }
    Ok(Value::str(&out))
}

fn b64_index(c: u16) -> Option<u32> {
    match c {
        0x41..=0x5A => Some((c - 0x41) as u32),
        0x61..=0x7A => Some((c - 0x61 + 26) as u32),
        0x30..=0x39 => Some((c - 0x30 + 52) as u32),
        0x2B => Some(62),
        0x2F => Some(63),
        _ => None,
    }
}

fn atob(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let s = js_string(vm, &a.arg(0))?;
    let mut u: Vec<u16> = s.units().iter().copied().filter(|&c| !matches!(c, 0x09 | 0x0A | 0x0C | 0x0D | 0x20)).collect();
    if u.len() % 4 == 0 && u.last() == Some(&0x3D) {
        u.pop();
        if u.last() == Some(&0x3D) {
            u.pop();
        }
    }
    if u.len() % 4 == 1 || u.iter().any(|&c| b64_index(c).is_none()) {
        return throw_dom(vm, "atob: invalid base64", "InvalidCharacterError");
    }
    let mut out: Vec<u16> = Vec::with_capacity(u.len() * 3 / 4);
    let mut i = 0;
    while i < u.len() {
        let bit = |j: usize| -> u32 { if i + j < u.len() { b64_index(u[i + j]).unwrap_or(0) } else { 0 } };
        let n = (bit(0) << 18) | (bit(1) << 12) | (bit(2) << 6) | bit(3);
        out.push(((n >> 16) & 255) as u16);
        if i + 2 < u.len() {
            out.push(((n >> 8) & 255) as u16);
        }
        if i + 3 < u.len() {
            out.push((n & 255) as u16);
        }
        i += 4;
    }
    Ok(Value::Str(JsStr::from_units(out)))
}

// structuredClone and the byte-level clone serializer (__serializeForClone /
// __deserializeClone) used for cross-thread messages.

use super::*;
use crate::object::*;
use crate::value::*;
use crate::vm::{JsResult, Vm};
use std::collections::HashMap;

pub fn setup(vm: &mut Vm) {
    let f = plain_fn(vm, "structuredClone", 1, structured_clone_fn);
    set_global(vm, "structuredClone", Value::Obj(f));
    let f = plain_fn(vm, "serializeForClone", 1, serialize_fn);
    set_global(vm, "__serializeForClone", Value::Obj(f));
    let f = plain_fn(vm, "deserializeClone", 1, deserialize_fn);
    set_global(vm, "__deserializeClone", Value::Obj(f));
}

fn structured_clone_fn(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    structured_clone(vm, &a.arg(0))
}

fn data_clone_error<T>(vm: &mut Vm, msg: &str) -> JsResult<T> {
    throw_dom(vm, msg, "DataCloneError")
}

fn is_view(v: &Value) -> bool {
    match v {
        Value::Obj(o) => matches!(o.borrow().kind, ObjKind::TypedArray(_) | ObjKind::DataView(_)),
        _ => false,
    }
}

fn time_clip(t: f64) -> f64 {
    if !t.is_finite() || t.abs() > 8.64e15 {
        return f64::NAN;
    }
    let r = t.trunc();
    if r == 0.0 {
        0.0
    } else {
        r
    }
}

fn new_date(vm: &mut Vm, t: f64) -> Value {
    Value::Obj(Obj::with_class(Some(vm.intr.date_proto.clone()), ObjKind::Date(time_clip(t)), "Date"))
}

fn new_set(vm: &Vm) -> Obj {
    Obj::with_class(Some(vm.intr.set_proto.clone()), ObjKind::Set(Box::new(OrderedMap::new())), "Set")
}

fn map_insert(m: &Obj, k: Value, v: Value) {
    if let ObjKind::Map(mm) = &mut m.borrow_mut().kind {
        mm.set(k, v);
    }
}

fn set_insert(s: &Obj, v: Value) {
    if let ObjKind::Set(ss) = &mut s.borrow_mut().kind {
        ss.set(v.clone(), v);
    }
}

/// `structuredClone(value)` (the reference's JS algorithm; no transfer list).
pub fn structured_clone(vm: &mut Vm, v: &Value) -> JsResult<Value> {
    let mut seen: HashMap<usize, Value> = HashMap::new();
    clone_value(vm, v, &mut seen)
}

fn clone_value(vm: &mut Vm, v: &Value, seen: &mut HashMap<usize, Value>) -> JsResult<Value> {
    if v.type_of() == "function" || matches!(v, Value::Sym(_)) {
        return data_clone_error(vm, "value could not be cloned");
    }
    let o = match v {
        Value::Obj(o) => o.clone(),
        _ => return Ok(v.clone()),
    };
    if let Some(c) = seen.get(&o.addr()) {
        return Ok(c.clone());
    }
    let dp = vm.intr.date_proto.clone();
    if has_in_chain(vm, v, &dp)? {
        let t = invoke(vm, v, "getTime", &[])?;
        let n = vm.to_number(&t)?;
        return Ok(new_date(vm, n));
    }
    let rp = vm.intr.regexp_proto.clone();
    if has_in_chain(vm, v, &rp)? {
        let src = get(vm, v, "source")?;
        let flags = get(vm, v, "flags")?;
        return crate::builtins::regexp::regexp_create(vm, &src, &flags);
    }
    let pp = vm.intr.promise_proto.clone();
    if has_in_chain(vm, v, &pp)? {
        return data_clone_error(vm, "a Promise cannot be cloned");
    }
    let abp = vm.intr.array_buffer_proto.clone();
    if has_in_chain(vm, v, &abp)? {
        let c = invoke(vm, v, "slice", &[Value::Num(0.0)])?;
        seen.insert(o.addr(), c.clone());
        return Ok(c);
    }
    let dvp = vm.intr.data_view_proto.clone();
    if is_view(v) && !has_in_chain(vm, v, &dvp)? {
        let ctor = get(vm, v, "constructor")?;
        let c = vm.construct(&ctor, &[v.clone()], None)?;
        seen.insert(o.addr(), c.clone());
        return Ok(c);
    }
    let mp = vm.intr.map_proto.clone();
    if has_in_chain(vm, v, &mp)? {
        let m = new_map(vm);
        seen.insert(o.addr(), Value::Obj(m.clone()));
        let entries = vm.iterate_to_vec(v)?;
        for e in entries {
            let k = get_key(vm, &e, &PropKey::from_index(0))?;
            let val = get_key(vm, &e, &PropKey::from_index(1))?;
            let ck = clone_value(vm, &k, seen)?;
            let cv = clone_value(vm, &val, seen)?;
            map_insert(&m, ck, cv);
        }
        return Ok(Value::Obj(m));
    }
    let sp = vm.intr.set_proto.clone();
    if has_in_chain(vm, v, &sp)? {
        let s = new_set(vm);
        seen.insert(o.addr(), Value::Obj(s.clone()));
        let items = vm.iterate_to_vec(v)?;
        for it in items {
            let c = clone_value(vm, &it, seen)?;
            set_insert(&s, c);
        }
        return Ok(Value::Obj(s));
    }
    let ep = vm.intr.error_proto.clone();
    if has_in_chain(vm, v, &ep)? {
        let c = get(vm, v, "constructor")?;
        let ctor = if c.is_callable() { c } else { Value::Obj(error_ctor(vm)) };
        let msg = get(vm, v, "message")?;
        let e = vm.construct(&ctor, &[msg], None)?;
        let name = get(vm, v, "name")?;
        set(vm, &e, "name", name)?;
        seen.insert(o.addr(), e.clone());
        return Ok(e);
    }
    if crate::builtins::array::is_array(vm, v)? {
        let arr = vm.new_array(Vec::new());
        let av = Value::Obj(arr.clone());
        seen.insert(o.addr(), av.clone());
        let mut i: u64 = 0;
        loop {
            let len = get(vm, v, "length")?;
            let len = vm.to_number(&len)?;
            if !((i as f64) < len) {
                break;
            }
            let k = PropKey::from_index(i as u32);
            if vm.has_property(&o, &k)? {
                let item = vm.get(&o, &k, v)?;
                let c = clone_value(vm, &item, seen)?;
                vm.set_prop_of(&av, k, c, true)?;
            }
            i += 1;
        }
        return Ok(av);
    }
    let out = vm.new_object();
    let ov = Value::Obj(out.clone());
    seen.insert(o.addr(), ov.clone());
    let keys = vm.enumerable_own_keys(&o)?;
    for k in keys {
        let pk = PropKey::Str(k);
        let item = vm.get(&o, &pk, v)?;
        let c = clone_value(vm, &item, seen)?;
        vm.set_prop_of(&ov, pk, c, true)?;
    }
    Ok(ov)
}

fn error_ctor(vm: &mut Vm) -> Obj {
    match vm.intr.error_proto.get_own_str("constructor") {
        Some(Value::Obj(c)) => c,
        _ => vm.intr.object_proto.clone(),
    }
}

// ---------------------------------------------------------------------------------------------
// byte serializer
// ---------------------------------------------------------------------------------------------

const T_UNDEFINED: u8 = 0;
const T_NULL: u8 = 1;
const T_FALSE: u8 = 2;
const T_TRUE: u8 = 3;
const T_NUMBER: u8 = 4;
const T_STRING: u8 = 5;
const T_BIGINT: u8 = 6;
const T_REF: u8 = 7;
const T_ARRAY: u8 = 8;
const T_OBJECT: u8 = 9;
const T_DATE: u8 = 10;
const T_REGEXP: u8 = 11;
const T_MAP: u8 = 12;
const T_SET: u8 = 13;
const T_ARRAYBUFFER: u8 = 14;
const T_TYPEDARRAY: u8 = 15;
const T_DATAVIEW: u8 = 16;
const T_ERROR: u8 = 17;
const T_BOOLOBJ: u8 = 18;
const T_NUMOBJ: u8 = 19;
const T_STROBJ: u8 = 20;

const TA_KINDS: [&str; 11] = [
    "Int8Array",
    "Uint8Array",
    "Uint8ClampedArray",
    "Int16Array",
    "Uint16Array",
    "Int32Array",
    "Uint32Array",
    "Float32Array",
    "Float64Array",
    "BigInt64Array",
    "BigUint64Array",
];
const ERROR_NAMES: [&str; 7] = ["Error", "TypeError", "RangeError", "ReferenceError", "SyntaxError", "EvalError", "URIError"];

struct Ser {
    out: Vec<u8>,
    memory: HashMap<usize, u32>,
}

impl Ser {
    fn u8(&mut self, n: u8) {
        self.out.push(n);
    }
    fn u32(&mut self, n: u32) {
        self.out.extend_from_slice(&n.to_le_bytes());
    }
    fn f64(&mut self, n: f64) {
        self.out.extend_from_slice(&n.to_le_bytes());
    }
    fn raw(&mut self, b: &[u8]) {
        self.out.extend_from_slice(b);
    }
}

fn ser_str(vm: &mut Vm, s: &mut Ser, v: &Value) -> JsResult<()> {
    let st = js_string(vm, v)?;
    let enc = super::encoding::engine_utf8(st.units());
    s.u32(enc.len() as u32);
    s.raw(&enc);
    Ok(())
}

fn to_u32(vm: &mut Vm, v: &Value) -> JsResult<u32> {
    vm.to_uint32(v)
}

fn ser_write(vm: &mut Vm, s: &mut Ser, v: &Value) -> JsResult<()> {
    match v {
        Value::Undefined | Value::Empty => {
            s.u8(T_UNDEFINED);
            return Ok(());
        }
        Value::Null => {
            s.u8(T_NULL);
            return Ok(());
        }
        Value::Bool(b) => {
            s.u8(if *b { T_TRUE } else { T_FALSE });
            return Ok(());
        }
        Value::Num(n) => {
            s.u8(T_NUMBER);
            s.f64(*n);
            return Ok(());
        }
        Value::Str(_) => {
            s.u8(T_STRING);
            return ser_str(vm, s, v);
        }
        Value::BigInt(b) => {
            s.u8(T_BIGINT);
            let t = Value::str(&b.to_string_radix(10));
            return ser_str(vm, s, &t);
        }
        Value::Sym(_) => return data_clone_error(vm, "value could not be cloned"),
        Value::Obj(_) => {}
    }
    if v.type_of() == "function" {
        return data_clone_error(vm, "value could not be cloned");
    }
    let o = v.as_obj().unwrap().clone();
    if let Some(r) = s.memory.get(&o.addr()) {
        let r = *r;
        s.u8(T_REF);
        s.u32(r);
        return Ok(());
    }
    let r = s.memory.len() as u32;
    let dp = vm.intr.date_proto.clone();
    if has_in_chain(vm, v, &dp)? {
        s.u8(T_DATE);
        let t = invoke(vm, v, "getTime", &[])?;
        let n = vm.to_number(&t)?;
        s.f64(n);
        return Ok(());
    }
    let rp = vm.intr.regexp_proto.clone();
    if has_in_chain(vm, v, &rp)? {
        s.u8(T_REGEXP);
        let src = get(vm, v, "source")?;
        ser_str(vm, s, &src)?;
        let flags = get(vm, v, "flags")?;
        return ser_str(vm, s, &flags);
    }
    let pp = vm.intr.promise_proto.clone();
    if has_in_chain(vm, v, &pp)? {
        return data_clone_error(vm, "a Promise cannot be cloned");
    }
    let abp = vm.intr.array_buffer_proto.clone();
    if has_in_chain(vm, v, &abp)? {
        s.memory.insert(o.addr(), r);
        s.u8(T_ARRAYBUFFER);
        let bytes = crate::builtins::typedarray::ta_bytes(&o);
        s.u32(bytes.len() as u32);
        s.raw(&bytes);
        return Ok(());
    }
    let dvp = vm.intr.data_view_proto.clone();
    if has_in_chain(vm, v, &dvp)? {
        s.memory.insert(o.addr(), r);
        s.u8(T_DATAVIEW);
        let bo = get(vm, v, "byteOffset")?;
        let bo = to_u32(vm, &bo)?;
        s.u32(bo);
        let bl = get(vm, v, "byteLength")?;
        let bl = to_u32(vm, &bl)?;
        s.u32(bl);
        let buf = get(vm, v, "buffer")?;
        return ser_write(vm, s, &buf);
    }
    if is_view(v) {
        let ctor = get(vm, v, "constructor")?;
        let name = get(vm, &ctor, "name")?;
        let kind = match &name {
            Value::Str(n) => TA_KINDS.iter().position(|k| n.eq_str(k)),
            _ => None,
        };
        let kind = match kind {
            Some(k) => k,
            None => return data_clone_error(vm, "unsupported typed array"),
        };
        s.memory.insert(o.addr(), r);
        s.u8(T_TYPEDARRAY);
        s.u8(kind as u8);
        let bo = get(vm, v, "byteOffset")?;
        let bo = to_u32(vm, &bo)?;
        s.u32(bo);
        let l = get(vm, v, "length")?;
        let l = to_u32(vm, &l)?;
        s.u32(l);
        let buf = get(vm, v, "buffer")?;
        return ser_write(vm, s, &buf);
    }
    let mp = vm.intr.map_proto.clone();
    if has_in_chain(vm, v, &mp)? {
        s.memory.insert(o.addr(), r);
        s.u8(T_MAP);
        let size = get(vm, v, "size")?;
        let size = to_u32(vm, &size)?;
        s.u32(size);
        for e in vm.iterate_to_vec(v)? {
            let k = get_key(vm, &e, &PropKey::from_index(0))?;
            let val = get_key(vm, &e, &PropKey::from_index(1))?;
            ser_write(vm, s, &k)?;
            ser_write(vm, s, &val)?;
        }
        return Ok(());
    }
    let sp = vm.intr.set_proto.clone();
    if has_in_chain(vm, v, &sp)? {
        s.memory.insert(o.addr(), r);
        s.u8(T_SET);
        let size = get(vm, v, "size")?;
        let size = to_u32(vm, &size)?;
        s.u32(size);
        for it in vm.iterate_to_vec(v)? {
            ser_write(vm, s, &it)?;
        }
        return Ok(());
    }
    let ep = vm.intr.error_proto.clone();
    if has_in_chain(vm, v, &ep)? {
        s.memory.insert(o.addr(), r);
        s.u8(T_ERROR);
        let name = get(vm, v, "name")?;
        let idx = match &name {
            Value::Str(n) => ERROR_NAMES.iter().position(|k| n.eq_str(k)).unwrap_or(0),
            _ => 0,
        };
        s.u8(idx as u8);
        let msg = get(vm, v, "message")?;
        ser_str(vm, s, &msg)?;
        let stack = get(vm, v, "stack")?;
        let stack = if stack.is_nullish() { Value::str("") } else { stack };
        return ser_str(vm, s, &stack);
    }
    let ots = get(vm, &Value::Obj(vm.intr.object_proto.clone()), "toString")?;
    let tag = vm.call(&ots, v.clone(), &[])?;
    let tag = match &tag {
        Value::Str(t) => t.to_rust_string(),
        _ => String::new(),
    };
    if tag == "[object Boolean]" {
        s.memory.insert(o.addr(), r);
        s.u8(T_BOOLOBJ);
        let b = invoke(vm, v, "valueOf", &[])?;
        s.u8(if b.truthy() { 1 } else { 0 });
        return Ok(());
    }
    if tag == "[object Number]" {
        s.memory.insert(o.addr(), r);
        s.u8(T_NUMOBJ);
        let n = invoke(vm, v, "valueOf", &[])?;
        let n = vm.to_number(&n)?;
        s.f64(n);
        return Ok(());
    }
    if tag == "[object String]" {
        s.memory.insert(o.addr(), r);
        s.u8(T_STROBJ);
        let st = invoke(vm, v, "valueOf", &[])?;
        return ser_str(vm, s, &st);
    }
    if crate::builtins::array::is_array(vm, v)? {
        s.memory.insert(o.addr(), r);
        s.u8(T_ARRAY);
        let len = get(vm, v, "length")?;
        let len = to_u32(vm, &len)?;
        s.u32(len);
        let mut i: u64 = 0;
        loop {
            let l = get(vm, v, "length")?;
            let l = vm.to_number(&l)?;
            if !((i as f64) < l) {
                break;
            }
            let item = vm.get(&o, &PropKey::from_index(i as u32), v)?;
            ser_write(vm, s, &item)?;
            i += 1;
        }
        return Ok(());
    }
    s.memory.insert(o.addr(), r);
    s.u8(T_OBJECT);
    let keys = vm.enumerable_own_keys(&o)?;
    s.u32(keys.len() as u32);
    for k in keys {
        let kv = Value::Str(k.clone());
        ser_str(vm, s, &kv)?;
        let item = vm.get(&o, &PropKey::Str(k), v)?;
        ser_write(vm, s, &item)?;
    }
    Ok(())
}

fn serialize_fn(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let mut s = Ser { out: Vec::new(), memory: HashMap::new() };
    ser_write(vm, &mut s, &a.arg(0))?;
    let len = s.out.len();
    let mut cap = 64;
    while cap < len {
        cap *= 2;
    }
    let mut bytes = s.out;
    bytes.resize(cap, 0);
    let full = crate::builtins::typedarray::typed_array_from_bytes(vm, bytes);
    if let ObjKind::TypedArray(t) = &mut full.borrow_mut().kind {
        t.length = Some(len);
    }
    Ok(Value::Obj(full))
}

struct De {
    bytes: Vec<u8>,
    pos: usize,
    memory: Vec<Value>,
}

fn oob<T>(vm: &mut Vm) -> JsResult<T> {
    vm.throw_range("Offset is outside the bounds of the DataView")
}

impl De {
    fn u8(&mut self) -> Option<u8> {
        let b = self.bytes.get(self.pos).copied();
        self.pos += 1;
        b
    }
}

fn de_u32(vm: &mut Vm, d: &mut De) -> JsResult<u32> {
    if d.pos + 4 > d.bytes.len() {
        return oob(vm);
    }
    let n = u32::from_le_bytes([d.bytes[d.pos], d.bytes[d.pos + 1], d.bytes[d.pos + 2], d.bytes[d.pos + 3]]);
    d.pos += 4;
    Ok(n)
}

fn de_f64(vm: &mut Vm, d: &mut De) -> JsResult<f64> {
    if d.pos + 8 > d.bytes.len() {
        return oob(vm);
    }
    let mut b = [0u8; 8];
    b.copy_from_slice(&d.bytes[d.pos..d.pos + 8]);
    d.pos += 8;
    Ok(f64::from_le_bytes(b))
}

fn de_str(vm: &mut Vm, d: &mut De) -> JsResult<Value> {
    let len = de_u32(vm, d)? as usize;
    let start = d.pos.min(d.bytes.len());
    let end = d.pos.saturating_add(len).min(d.bytes.len());
    let s = super::encoding::decode_default(&d.bytes[start..end]);
    d.pos += len;
    Ok(Value::Str(s))
}

fn global_ctor(vm: &mut Vm, name: &str) -> JsResult<Value> {
    global_get(vm, name)
}

fn de_read(vm: &mut Vm, d: &mut De) -> JsResult<Value> {
    let tag = d.u8();
    match tag {
        Some(T_UNDEFINED) => Ok(Value::Undefined),
        Some(T_NULL) => Ok(Value::Null),
        Some(T_FALSE) => Ok(Value::Bool(false)),
        Some(T_TRUE) => Ok(Value::Bool(true)),
        Some(T_NUMBER) => Ok(Value::Num(de_f64(vm, d)?)),
        Some(T_STRING) => de_str(vm, d),
        Some(T_BIGINT) => {
            let s = de_str(vm, d)?;
            let f = global_ctor(vm, "BigInt")?;
            vm.call(&f, Value::Undefined, &[s])
        }
        Some(T_REF) => {
            let i = de_u32(vm, d)? as usize;
            Ok(d.memory.get(i).cloned().unwrap_or(Value::Undefined))
        }
        Some(T_DATE) => {
            let t = de_f64(vm, d)?;
            Ok(new_date(vm, t))
        }
        Some(T_REGEXP) => {
            let src = de_str(vm, d)?;
            let flags = de_str(vm, d)?;
            crate::builtins::regexp::regexp_create(vm, &src, &flags)
        }
        Some(T_ARRAYBUFFER) => {
            let len = de_u32(vm, d)? as usize;
            let mut bytes = vec![0u8; len];
            let start = d.pos.min(d.bytes.len());
            let end = d.pos.saturating_add(len).min(d.bytes.len());
            bytes[..end - start].copy_from_slice(&d.bytes[start..end]);
            d.pos += len;
            let ab = Value::Obj(crate::builtins::typedarray::new_array_buffer(vm, bytes));
            d.memory.push(ab.clone());
            Ok(ab)
        }
        Some(T_DATAVIEW) => {
            let bo = de_u32(vm, d)?;
            let bl = de_u32(vm, d)?;
            let ctor = global_ctor(vm, "DataView")?;
            let buf = de_read(vm, d)?;
            let dv = vm.construct(&ctor, &[buf, Value::Num(bo as f64), Value::Num(bl as f64)], None)?;
            d.memory.push(dv.clone());
            Ok(dv)
        }
        Some(T_TYPEDARRAY) => {
            let kind = d.u8().map(|k| k as usize).unwrap_or(usize::MAX);
            let bo = de_u32(vm, d)?;
            let len = de_u32(vm, d)?;
            let name = TA_KINDS.get(kind).copied().unwrap_or("undefined");
            let ctor = global_ctor(vm, name)?;
            let buf = de_read(vm, d)?;
            let ta = vm.construct(&ctor, &[buf, Value::Num(bo as f64), Value::Num(len as f64)], None)?;
            d.memory.push(ta.clone());
            Ok(ta)
        }
        Some(T_MAP) => {
            let m = new_map(vm);
            d.memory.push(Value::Obj(m.clone()));
            let n = de_u32(vm, d)?;
            for _ in 0..n {
                let k = de_read(vm, d)?;
                let v = de_read(vm, d)?;
                map_insert(&m, k, v);
            }
            Ok(Value::Obj(m))
        }
        Some(T_SET) => {
            let s = new_set(vm);
            d.memory.push(Value::Obj(s.clone()));
            let n = de_u32(vm, d)?;
            for _ in 0..n {
                let v = de_read(vm, d)?;
                set_insert(&s, v);
            }
            Ok(Value::Obj(s))
        }
        Some(T_ERROR) => {
            let idx = d.u8().map(|k| k as usize).unwrap_or(usize::MAX);
            let name = ERROR_NAMES.get(idx).copied().unwrap_or("undefined");
            let c = global_ctor(vm, name)?;
            let ctor = if c.is_nullish() { Value::Obj(error_ctor(vm)) } else { c };
            let msg = de_str(vm, d)?;
            let e = vm.construct(&ctor, &[msg], None)?;
            let stack = de_str(vm, d)?;
            set(vm, &e, "stack", stack)?;
            d.memory.push(e.clone());
            Ok(e)
        }
        Some(T_BOOLOBJ) => {
            let b = d.u8() == Some(1);
            let o = vm.to_object(&Value::Bool(b))?;
            d.memory.push(Value::Obj(o.clone()));
            Ok(Value::Obj(o))
        }
        Some(T_NUMOBJ) => {
            let n = de_f64(vm, d)?;
            let o = vm.to_object(&Value::Num(n))?;
            d.memory.push(Value::Obj(o.clone()));
            Ok(Value::Obj(o))
        }
        Some(T_STROBJ) => {
            let s = de_str(vm, d)?;
            let o = vm.to_object(&s)?;
            d.memory.push(Value::Obj(o.clone()));
            Ok(Value::Obj(o))
        }
        Some(T_ARRAY) => {
            let arr = vm.new_array(Vec::new());
            let av = Value::Obj(arr);
            d.memory.push(av.clone());
            let len = de_u32(vm, d)?;
            for i in 0..len {
                let v = de_read(vm, d)?;
                vm.set_prop_of(&av, PropKey::from_index(i), v, true)?;
            }
            Ok(av)
        }
        Some(T_OBJECT) => {
            let o = vm.new_object();
            let ov = Value::Obj(o);
            d.memory.push(ov.clone());
            let n = de_u32(vm, d)?;
            for _ in 0..n {
                let k = de_str(vm, d)?;
                let v = de_read(vm, d)?;
                let pk = vm.to_property_key(&k)?;
                vm.set_prop_of(&ov, pk, v, true)?;
            }
            Ok(ov)
        }
        _ => data_clone_error(vm, "malformed clone data"),
    }
}

fn deserialize_fn(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let buf = a.arg(0);
    let ab = get(vm, &buf, "buffer")?;
    let is_ab = matches!(&ab, Value::Obj(o) if matches!(o.borrow().kind, ObjKind::ArrayBuffer(_)));
    if !is_ab {
        return vm.throw_type("DataView requires an ArrayBuffer");
    }
    let bytes = match &buf {
        Value::Obj(o) => match &o.borrow().kind {
            ObjKind::TypedArray(_) | ObjKind::DataView(_) => None,
            _ => Some(Vec::new()),
        },
        _ => Some(Vec::new()),
    };
    let bytes = match bytes {
        Some(b) => b,
        None => crate::builtins::typedarray::ta_bytes(buf.as_obj().unwrap()),
    };
    let mut d = De { bytes, pos: 0, memory: Vec::new() };
    de_read(vm, &mut d)
}

