const log = (...a) => console.log(...a);
const et = new EventTarget();
const h1 = (e) => log('h1', e.type, e.target === et, e.currentTarget === et, e.eventPhase, e.isTrusted, e.bubbles, e.cancelable, e.defaultPrevented);
et.addEventListener('ping', h1);
et.addEventListener('ping', h1); // dup ignored
et.addEventListener('ping', h1, true); // different capture
et.addEventListener('ping', { handleEvent(e) { log('handleEvent', e.type, this !== et); } });
et.addEventListener('ping', (e) => log('once', e.type), { once: true });
log('dispatch1', et.dispatchEvent(new Event('ping')));
log('dispatch2', et.dispatchEvent(new Event('ping')));
et.removeEventListener('ping', h1);
log('dispatch3', et.dispatchEvent(new Event('ping')));
et.removeEventListener('ping', h1, { capture: true });
log('dispatch4', et.dispatchEvent(new Event('ping')));
// preventDefault
const et2 = new EventTarget();
et2.addEventListener('c', (e) => { e.preventDefault(); log('prevented?', e.defaultPrevented); });
log('cancelable result', et2.dispatchEvent(new Event('c', { cancelable: true })));
log('non-cancelable result', et2.dispatchEvent(new Event('c')));
// stopImmediatePropagation
const et3 = new EventTarget();
et3.addEventListener('s', (e) => { log('first'); e.stopImmediatePropagation(); });
et3.addEventListener('s', () => log('second (should not run)'));
et3.dispatchEvent(new Event('s'));
// listener throwing
const et4 = new EventTarget();
et4.addEventListener('t', () => { throw new Error('listener boom'); });
et4.addEventListener('t', () => log('after throw still runs'));
et4.addEventListener('t', () => { throw 'string thrown'; });
log('t result', et4.dispatchEvent(new Event('t')));
// signal option
const ac = new AbortController();
const et5 = new EventTarget();
et5.addEventListener('x', () => log('x listener'), { signal: ac.signal });
et5.dispatchEvent(new Event('x'));
ac.abort();
et5.dispatchEvent(new Event('x'));
et5.addEventListener('x', () => log('added after abort'), { signal: ac.signal });
et5.dispatchEvent(new Event('x'));
// CustomEvent
const ce = new CustomEvent('custom', { detail: { a: 1 }, bubbles: true });
log(ce.type, JSON.stringify(ce.detail), ce.bubbles, ce instanceof Event, ce instanceof CustomEvent, Object.prototype.toString.call(ce));
log(new CustomEvent('n').detail);
// Event props
const ev = new Event('foo', { bubbles: true, cancelable: true, composed: true });
log(JSON.stringify(Object.keys(ev)), ev.composed, typeof ev.timeStamp);
try { new Event(); } catch (e) { log(e.name, e.message); }
try { et.dispatchEvent({ type: 'fake' }); } catch (e) { log(e.name, e.message); }
try { et.dispatchEvent(); } catch (e) { log(e.name, e.message); }
// subclassing
class MyTarget extends EventTarget {
  constructor() { super(); this.n = 0; }
  fire() { this.dispatchEvent(new CustomEvent('inc', { detail: 5 })); }
}
const mt = new MyTarget();
mt.addEventListener('inc', (e) => { mt.n += e.detail; });
mt.fire(); mt.fire();
log('mt.n', mt.n, mt instanceof EventTarget, JSON.stringify(Object.keys(mt)));
class MyEvent extends Event { constructor(x) { super('my'); this.x = x; } }
const me = new MyEvent(42);
mt.addEventListener('my', (e) => log('my event', e.x, e instanceof MyEvent));
mt.dispatchEvent(me);
// null/undefined listener
et.addEventListener('z', null);
et.addEventListener('z', undefined);
log('z', et.dispatchEvent(new Event('z')));
// event constants
log(Event.NONE, Event.CAPTURING_PHASE, Event.AT_TARGET, Event.BUBBLING_PHASE);
// remove during dispatch
const et6 = new EventTarget();
const b = () => log('b should not run');
et6.addEventListener('r', () => { log('a removes b'); et6.removeEventListener('r', b); });
et6.addEventListener('r', b);
et6.dispatchEvent(new Event('r'));
// add during dispatch
et6.addEventListener('q', () => { log('q1'); et6.addEventListener('q', () => log('q-added')); });
et6.dispatchEvent(new Event('q'));
et6.dispatchEvent(new Event('q'));
// Event methods
const e7 = new Event('e7', { cancelable: true });
e7.stopPropagation();
log(e7._propagationStopped, e7._immediateStopped, e7.defaultPrevented);
e7.preventDefault();
log(e7.defaultPrevented);
log(typeof et.addEventListener, et.addEventListener.length, et.removeEventListener.length, et.dispatchEvent.length);
const evNum = new Event(42);
log(evNum.type, typeof evNum.type);
// passive option & options object variants
et6.addEventListener('p', () => log('passive'), { passive: true });
et6.dispatchEvent(new Event('p'));
et6.addEventListener('p', () => log('opt-false'), false);
et6.dispatchEvent(new Event('p'));

