const log = (...a) => console.log(...a);
const ac = new AbortController();
const s = ac.signal;
log(s.aborted, s.reason, s.onabort, s instanceof AbortSignal, s instanceof EventTarget, JSON.stringify(Object.keys(s)), JSON.stringify(Object.keys(ac)));
s.onabort = (e) => log('onabort', e.type, e instanceof Event, s.aborted);
s.addEventListener('abort', (e) => log('listener', e.type, e.target === s, s.reason.name));
ac.abort();
log(s.aborted, s.reason.name, s.reason.message, s.reason instanceof DOMException, s.reason.code, String(s.reason));
ac.abort('again'); // no-op
log(s.reason.name);
try { s.throwIfAborted(); } catch (e) { log('thrown', e.name, e === s.reason); }
const ac2 = new AbortController();
ac2.abort('custom');
log(ac2.signal.reason);
try { ac2.signal.throwIfAborted(); } catch (e) { log('thrown2', e); }
const ac3 = new AbortController();
ac3.signal.throwIfAborted();
log('not thrown');
const ab = AbortSignal.abort();
log(ab.aborted, ab.reason.name, ab.reason.message);
const ab2 = AbortSignal.abort(new Error('why'));
log(ab2.reason.message);
try { new AbortSignal(); } catch (e) { log(e.name, e.message); }
try { AbortSignal(); } catch (e) { log(e.name, e.message); }
const err = new Error('e1');
const ac4 = new AbortController();
const any = AbortSignal.any([ac4.signal, new AbortController().signal]);
any.addEventListener('abort', () => log('any aborted', any.reason === err));
ac4.abort(err);
const any2 = AbortSignal.any([AbortSignal.abort('pre')]);
log(any2.aborted, any2.reason);
try { AbortSignal.any(); } catch (e) { log(e.name, e.message); }
const t = AbortSignal.timeout(20);
t.onabort = () => log('timeout fired', t.reason.name, t.reason.message, t.reason.code);
log('timeout aborted yet?', t.aborted);
const ac5 = new AbortController();
ac5.signal.onabort = () => { throw new Error('onabort throws'); };
ac5.signal.addEventListener('abort', () => log('listener after throwing onabort'));
ac5.abort();
const ac6 = new AbortController();
ac6.signal.onabort = 'not a function';
ac6.abort();
log('ac6', ac6.signal.aborted);
log(typeof AbortSignal.abort, typeof AbortSignal.timeout, typeof AbortSignal.any, AbortSignal.any.name);
// DOMException basics
const de = new DOMException('msg', 'NotFoundError');
log(de.name, de.message, de.code, de instanceof Error, Object.prototype.toString.call(de), de.toString());
const de2 = new DOMException('x', { name: 'Weird' });
log(de2.name);
log(new DOMException().name, JSON.stringify(new DOMException().message));
// fetch-like abort pattern
function work(signal) {
  return new Promise((resolve, reject) => {
    const id = setTimeout(() => resolve('done'), 100);
    signal.addEventListener('abort', () => { clearTimeout(id); reject(signal.reason); }, { once: true });
  });
}
const ac7 = new AbortController();
work(ac7.signal).then(v => log('resolved', v), e => log('rejected', e.name, e.message));
setTimeout(() => ac7.abort(), 10);

