const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
const pieces = ['http', 'https', 'ftp', 'ws', 'wss', 'file', 'mailto', 'data', 'custom', 'HTTP', 'a+b', ':', '//', '/', '?', '#', '@', '[', ']', '::1', 'user', 'pw', 'host', 'HOST', '.', '..', '%20', '%zz', ' ', '\t', '\\', '80', '443', '8080', '0', '65536', 'x', 'ü', 'é', '&', '=', '+', '\u0000', 'localhost', '127.0.0.1', 'a.b.c', '-', '_', '~', '*'];
const bases = [undefined, 'http://base.com/a/b?q#f', 'file:///dir/file', 'custom:opaque', 'custom://h/p/q', 'mailto:x@y', 'not a base', ''];
const N = Number(process.argv[3] || 2000);
for (let i = 0; i < N; i++) {
  let s = '';
