/// A plain function carrying captured values (read with `a.slot(i)` inside `f`).
pub fn plain_closure(vm: &mut Vm, name: &str, len: u32, f: NativeFn, slots: Vec<Value>) -> Obj {
    let inner = vm.native_closure(name, len, f, slots);
    let outer = vm.native_closure(name, len, plain_closure_shim, vec![Value::Obj(inner)]);
    vm.make_ctor(&outer);
    let proto = vm.new_object();
    proto.set_prop(vm.intr.key_constructor.clone(), Value::Obj(outer.clone()), WC);
    outer.set_prop(vm.intr.key_prototype.clone(), Value::Obj(proto), WRITABLE);
    outer
}

fn plain_closure_shim(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    plain_fn_shim(vm, a)
}

